            int inkTop=(int)Math.floor(actualBaseline+glyph.top),inkBottom=(int)Math.ceil(actualBaseline+glyph.bottom);
            int clipTop=custom?0:label.getExtendedPaddingTop()+label.getScrollY(),clipBottom=custom?label.getHeight():label.getHeight()-label.getExtendedPaddingBottom()+label.getScrollY();
            Paint.FontMetricsInt fm=label.getPaint().getFontMetricsInt();android.text.Layout layout=label.getLayout();Rect visible=global(label);int[] screen=new int[2];ui(()->label.getLocationOnScreen(screen));
